DECLARE @Violations INT=(SELECT COUNT(*) FROM dbo.BOOKING_REQUEST a JOIN dbo.BOOKING_STATUS sa ON sa.booking_status_id=a.booking_status_id JOIN dbo.BOOKING_REQUEST b ON b.space_id=a.space_id AND b.booking_request_id>a.booking_request_id JOIN dbo.BOOKING_STATUS sb ON sb.booking_status_id=b.booking_status_id JOIN dbo.SPACE s ON s.space_id=a.space_id WHERE s.unique_space_code=N'G03-CT-UNSAFE' AND sa.status_code IN(N'approved',N'checked_in') AND sb.status_code IN(N'approved',N'checked_in') AND a.requested_start_time<b.requested_end_time AND a.requested_end_time>b.requested_start_time);
SELECT @Violations AS unsafe_overlap_pairs,CASE WHEN @Violations>0 THEN N'PASS: race reproduced' ELSE N'FAIL' END AS result;
